r = await world.call('repo.read_file', path='src/semver/version.py')
lines = r['content'].split('\n')

# Find bump_prerelease
start = None
for i, line in enumerate(lines):
    if 'def bump_prerelease' in line:
        start = i
        break

if start:
    end = start + 1
    indent_level = len(lines[start]) - len(lines[start].lstrip())
    while end < len(lines):
        current_indent = len(lines[end]) - len(lines[end].lstrip()) if lines[end].strip() else indent_level + 1
        if lines[end].strip() and current_indent <= indent_level and not lines[end].strip().startswith('#'):
            break
        end += 1
    print("=== bump_prerelease (lines {}-{}) ===".format(start+1, end))
    for i in range(start, min(end, start+50)):
        print(f"{i+1}: {lines[i]}")
